def parse_csv_line(line):
    """Parse a single CSV line into a list of cell strings."""
    parts = line.split(",")
    cleaned = []
    for p in parts:
        p = p.strip()
        if p.startswith('"') and p.endswith('"'):
            p = p[1:-1]
        cleaned.append(p)
    return cleaned

